import re, sys
with open("crypto_primary_knowledge/output.txt","r") as f:
    content = f.read()

def find_int(name):
    m = re.search(rf"{name}\\s*=\\s*(\\d+)", content)
    if not m:
        # Try without raw backslashes if above fails (robustness across shells)
        m = re.search(name + r"\\s*=\\s*(\\d+)", content)
    if not m:
        print(f"Parse error for {name}", file=sys.stderr)
        print(content, file=sys.stderr)
        sys.exit(1)
    return int(m.group(1))

# Correct patterns without double-escaping
def find_int_fixed(name):
    m = re.search(rf"{name}\s*=\s*(\d+)", content)
    if not m:
        print(f"Parse error for {name}", file=sys.stderr)
        print(content, file=sys.stderr)
        sys.exit(1)
    return int(m.group(1))

n = find_int_fixed("n")
e = find_int_fixed("e")
c = find_int_fixed("c")

phi = n - 1

# Compute modular inverse of e mod phi
try:
    d = pow(e, -1, phi)
except TypeError:
    def egcd(a, b):
        if b == 0:
            return (a, 1, 0)
        g, x1, y1 = egcd(b, a % b)
        return (g, y1, x1 - (a // b) * y1)
    g, x, y = egcd(e, phi)
    if g != 1:
        print("No modular inverse exists", file=sys.stderr)
        sys.exit(1)
    d = x % phi

m = pow(c, d, n)
pt = m.to_bytes((m.bit_length() + 7) // 8, "big")

print(pt)
try:
    print(pt.decode())
except Exception:
    print(pt.rstrip(b"\\x00").decode(errors="ignore"))
EOF'
